def calcular_morosidad(df: pd.DataFrame, anio: int, mes: str) -> dict:
    """
    Calcula el índice de mora para un período dado.
    
    Estructura (basada en el Excel oficial - cuentas 840xxx-842xxx):
      - 5 grupos de cartera: Vivienda, Consumo c/libranza, Consumo s/libranza,
        Microcrédito, Comercial.
      - 5 categorías de mora por cada grupo: A (vigente), B, C, D, E (vencida)
      
    Cuentas (6 dígitos exactos):
      840505-840525: Vivienda (A-E)
      841005-841025: Consumo con libranza (A-E)
      841505-841525: Consumo sin libranza (A-E)
      842005-842025: Microcrédito (A-E)
      842505-842525: Comercial (A-E)
      
    Índice de mora = (B+C+D+E) / TOTAL
    """
    # Filtro: solo cuentas con EXACTAMENTE 6 dígitos (las "padre")
    # Las cuentas 9 dígitos (840505001, etc.) son auxiliares que duplican el saldo
    df_p = df[(df["AÑO"] == anio) & (df["MES"] == mes.upper())]
    
    def sumar_exacta(cuenta: str) -> float:
        """Suma SOLO las filas con CUENTA igual al código (no startswith)."""
        s = df_p[df_p["CUENTA"] == cuenta]["NUEVO SALDO"].abs().sum()
        return s / 1_000_000  # millones
    
    GRUPOS = [
        {
            "nombre": "Vivienda",
            "codigo": "840500",
            "descripcion": "Morosidad cartera de vivienda",
            "cuentas": [
                ("840505", "A", "Capital vigente y hasta 60 días de mora"),
                ("840510", "B", "Capital con mora mayor a 60 días y hasta 150 días"),
                ("840515", "C", "Capital con mora mayor a 150 días y hasta 360 días"),
                ("840520", "D", "Capital con mora mayor a 360 días y hasta 540 días"),
                ("840525", "E", "Capital con mora mayor a 540 días"),
            ],
        },
        {
            "nombre": "Consumo con libranza",
            "codigo": "841000",
            "descripcion": "Morosidad cartera de consumo con libranza",
            "cuentas": [
                ("841005", "A", "Capital vigente y hasta 30 días de mora"),
                ("841010", "B", "Capital con mora mayor a 30 días y hasta 60 días"),
                ("841015", "C", "Capital con mora mayor a 60 días y hasta 90 días"),
                ("841020", "D", "Capital con mora mayor a 90 días y hasta 180 días"),
                ("841025", "E", "Capital con mora mayor a 180 días"),
            ],
        },
        {
            "nombre": "Consumo sin libranza",
            "codigo": "841500",
            "descripcion": "Morosidad cartera de consumo sin libranza",
            "cuentas": [
                ("841505", "A", "Capital vigente y hasta 30 días de mora"),
                ("841510", "B", "Capital con mora mayor a 30 días y hasta 60 días"),
                ("841515", "C", "Capital con mora mayor a 60 días y hasta 90 días"),
                ("841520", "D", "Capital con mora mayor a 90 días y hasta 180 días"),
                ("841525", "E", "Capital con mora mayor a 180 días"),
            ],
        },
        {
            "nombre": "Microcrédito",
            "codigo": "842000",
            "descripcion": "Morosidad cartera de microcrédito",
            "cuentas": [
                ("842005", "A", "Capital vigente y hasta 30 días de mora"),
                ("842010", "B", "Capital con mora mayor a 30 días y hasta 60 días"),
                ("842015", "C", "Capital con mora mayor a 60 días y hasta 90 días"),
                ("842020", "D", "Capital con mora mayor a 90 días y hasta 120 días"),
                ("842025", "E", "Capital con mora mayor a 120 días"),
            ],
        },
        {
            "nombre": "Comercial",
            "codigo": "842500",
            "descripcion": "Morosidad cartera comercial",
            "cuentas": [
                ("842505", "A", "Capital vigente y hasta 30 días de mora"),
                ("842510", "B", "Capital con mora mayor a 30 días y hasta 90 días"),
                ("842515", "C", "Capital con mora mayor a 90 días y hasta 120 días"),
                ("842520", "D", "Capital con mora mayor a 120 días y hasta 150 días"),
                ("842525", "E", "Capital con mora mayor a 150 días"),
            ],
        },
    ]
    
    # Calcular cada grupo
    grupos_resultado = []
    total_general = 0.0
    mora_por_categoria = {"A": 0.0, "B": 0.0, "C": 0.0, "D": 0.0, "E": 0.0}
    mora_por_grupo = {}
    
    for grupo in GRUPOS:
        items = []
        subtotal = 0.0
        sub_por_categoria = {"A": 0.0, "B": 0.0, "C": 0.0, "D": 0.0, "E": 0.0}
        
        for cuenta, categoria, desc in grupo["cuentas"]:
            valor = sumar_exacta(cuenta)
            items.append({
                "codigo": cuenta,
                "descripcion": desc,
                "categoria": categoria,
                "valor": valor,
            })
            subtotal += valor
            sub_por_categoria[categoria] += valor
            mora_por_categoria[categoria] += valor
        
        total_general += subtotal
        # Mora del grupo = B + C + D + E
        mora_grupo = sub_por_categoria["B"] + sub_por_categoria["C"] + sub_por_categoria["D"] + sub_por_categoria["E"]
        indice_grupo = (mora_grupo / subtotal) if subtotal > 0 else 0.0
        
        mora_por_grupo[grupo["codigo"]] = {
            "mora": mora_grupo,
            "indice": indice_grupo,
        }
        
        grupos_resultado.append({
            "nombre": grupo["nombre"],
            "codigo": grupo["codigo"],
            "descripcion": grupo["descripcion"],
            "items": items,
            "subtotal": subtotal,
            "mora": mora_grupo,
            "indice_grupo": indice_grupo,
            "por_categoria": sub_por_categoria,
        })
    
    # Mora total e índice de mora general
    mora_total = mora_por_categoria["B"] + mora_por_categoria["C"] + mora_por_categoria["D"] + mora_por_categoria["E"]
    indice_mora = (mora_total / total_general) if total_general > 0 else 0.0
    
    # Saldos individuales de cuentas PUC (auditable)
    cuentas_mora = [
        '840505','840510','840515','840520','840525',
        '841005','841010','841015','841020','841025',
        '841505','841510','841515','841520','841525',
        '842005','842010','842015','842020','842025',
        '842505','842510','842515','842520','842525',
    ]
    saldos_cuentas = {}
    for c in cuentas_mora:
        s = df_p[df_p["CUENTA"] == c]["NUEVO SALDO"].abs().sum()
        saldos_cuentas[c] = s / 1_000_000  # millones
    
    return {
        "periodo": f"{mes.upper()} {anio}",
        "anio": anio,
        "mes": mes.upper(),
        "grupos": grupos_resultado,
        "total_general": total_general,
        "mora_total": mora_total,
        "indice_mora": indice_mora,
        "por_categoria": mora_por_categoria,
        "mora_por_grupo": mora_por_grupo,
        "saldos_cuentas": saldos_cuentas,
    }


def calcular_riesgo(df: pd.DataFrame, anio: int, mes: str) -> dict:
    """
    Calcula el Índice de Calidad de Cartera (clasificación por riesgo crediticio).
    
    Estructura (basada en el Excel oficial - cuentas 14xxxx):
      - Cartera bruta = suma de cuentas 4 dígitos:
        1404, 1405, 1411, 1412, 1441, 1442, 1448, 1454, 1455, 1461, 1462, 1469
      - Categorías B-E: cuentas 6 dígitos terminadas en 10, 15, 20, 25
        (riesgo aceptable, apreciable, significativo, incobrabilidad)
      - Categoría A = Cartera Capital − (B+C+D+E)
      
    Calidad de cartera = (B + C + D + E) / Cartera Capital
    """
    df_p = df[(df["AÑO"] == anio) & (df["MES"] == mes.upper())]
    
    def sumar_exacta(cuenta: str) -> float:
        s = df_p[df_p["CUENTA"] == cuenta]["NUEVO SALDO"].abs().sum()
        return s / 1_000_000  # millones
    
    # Cartera Bruta - cuentas de 4 dígitos
    CUENTAS_BRUTA = [
        ("1404", "Créditos de vivienda - con libranza"),
        ("1405", "Créditos de vivienda - sin libranza"),
        ("1411", "Créditos de consumo, garantía admisible - con libranza"),
        ("1412", "Créditos de consumo, garantía admisible - sin libranza"),
        ("1441", "Créditos de consumo, otras garantías - con libranza"),
        ("1442", "Créditos de consumo, otras garantías - sin libranza"),
        ("1448", "Cartera 1448"),
        ("1454", "Cartera 1454"),
        ("1455", "Cartera 1455"),
        ("1461", "Cartera 1461"),
        ("1462", "Cartera 1462"),
        ("1469", "Créditos a empleados"),
    ]
    
    # Cuentas por categoría (terminadas en 10=B, 15=C, 20=D, 25=E)
    PREFIJOS = ["1404", "1405", "1411", "1412", "1441", "1442", "1448", "1454", "1455", "1461", "1462", "1469"]
    
    cuentas_por_categoria = {
        "B": [],  # terminadas en 10
        "C": [],  # terminadas en 15
        "D": [],  # terminadas en 20
        "E": [],  # terminadas en 25
    }
    
    # Las cuentas 6 dígitos: PREFIJO(4) + "10"/"15"/"20"/"25"
    # Solo prefijos que tienen subcuentas:
    PREFIJOS_CON_SUB = ["1404", "1405", "1411", "1412", "1441", "1442", "1448", "1454", "1455", "1461", "1462", "1469"]
    SUFIJOS_CATEGORIAS = {"10": "B", "15": "C", "20": "D", "25": "E"}
    
    for pref in PREFIJOS_CON_SUB:
        for sufijo, cat in SUFIJOS_CATEGORIAS.items():
            cuenta = pref + sufijo
            cuentas_por_categoria[cat].append(cuenta)
    
    # Calcular cartera bruta (con detalle por línea)
    items_bruta = []
    cartera_total = 0.0
    for cuenta, desc in CUENTAS_BRUTA:
        valor = sumar_exacta(cuenta)
        items_bruta.append({
            "codigo": cuenta,
            "descripcion": desc,
            "valor": valor,
        })
        cartera_total += valor
    
    # Calcular cada categoría B, C, D, E (con detalle)
    detalle_categorias = {}
    totales = {"B": 0.0, "C": 0.0, "D": 0.0, "E": 0.0}
    nombres_categoria = {
        "B": "Riesgo Aceptable",
        "C": "Riesgo Apreciable",
        "D": "Riesgo Significativo",
        "E": "Riesgo de Incobrabilidad",
    }
    
    for cat, cuentas in cuentas_por_categoria.items():
        items = []
        for cuenta in cuentas:
            valor = sumar_exacta(cuenta)
            items.append({
                "codigo": cuenta,
                "descripcion": f"Categoría {cat} - {nombres_categoria[cat]}",
                "valor": valor,
            })
            totales[cat] += valor
        detalle_categorias[cat] = items
    
    # Categoría A = Total - (B+C+D+E)
    total_bcde = totales["B"] + totales["C"] + totales["D"] + totales["E"]
    cartera_A = cartera_total - total_bcde
    
    # Índice de calidad
    calidad_cartera = (total_bcde / cartera_total) if cartera_total > 0 else 0.0
    
    # ============================================================
    # INDICADORES POR MODALIDAD (Anexo Técnico)
    # ============================================================
    # Fórmula: Calidad x Riesgo = (B+C+D+E de la modalidad) / Cartera Bruta de la modalidad
    #          Calidad x Mora = (Cartera Vencida >30 días o >60 vivienda) / Cartera Bruta de la modalidad
    # ============================================================
    
    def calc_indicador(num_cuentas, den_cuentas):
        """Helper para calcular un indicador (numerador/denominador)."""
        num = sum(sumar_exacta(c) for c in num_cuentas)
        den = sum(sumar_exacta(c) for c in den_cuentas)
        indice = (num / den) if den > 0 else 0.0
        return {
            "numerador": num,
            "denominador": den,
            "indice": indice,
            "num_cuentas": num_cuentas,
            "den_cuentas": den_cuentas,
        }
    
    # === INDICADORES POR RIESGO (Calidad x Riesgo B,C,D,E) ===
    indicadores_riesgo_modalidad = {
        "consumo_sin_libranza": {
            "nombre": "Consumo Sin Libranza",
            "concepto": "Calidad x Riesgo (B,C,D,E)",
            "descripcion_formula": "Cartera Calificada en Categorías B, C, D y E 'Consumo SL' / Cartera Bruta 'Consumo SL'",
            "formula_texto": "(141210+141215+141220+141225+144210+144215+144220+144225) / (1412+1442)",
            **calc_indicador(
                ["141210","141215","141220","141225","144210","144215","144220","144225"],
                ["1412","1442"]
            ),
        },
        "consumo_con_libranza": {
            "nombre": "Consumo Con Libranza",
            "concepto": "Calidad x Riesgo (B,C,D,E)",
            "descripcion_formula": "Cartera Calificada en Categorías B, C, D y E 'Consumo CL' / Cartera Bruta 'Consumo CL'",
            "formula_texto": "(141110+141115+141120+141125+144110+144115+144120+144125+146935+146940+146945+146950) / (1411+1441+146930+146935+146940+146945+146950)",
            **calc_indicador(
                ["141110","141115","141120","141125","144110","144115","144120","144125","146935","146940","146945","146950"],
                ["1411","1441","146930","146935","146940","146945","146950"]
            ),
        },
        "comercial": {
            "nombre": "Comercial",
            "concepto": "Calidad x Riesgo (B,C,D,E)",
            "descripcion_formula": "Cartera Calificada en Categorías B, C, D y E 'Comercial' / Cartera Bruta 'Comercial'",
            "formula_texto": "(146110+146210+146115+146215+146120+146220+146125+146225) / (1461+1462)",
            **calc_indicador(
                ["146110","146210","146115","146215","146120","146220","146125","146225"],
                ["1461","1462"]
            ),
        },
        "microcredito": {
            "nombre": "Microcrédito",
            "concepto": "Calidad x Riesgo (B,C,D,E)",
            "descripcion_formula": "Cartera Calificada en Categorías B, C, D y E 'Microcrédito' / Cartera Bruta",
            "formula_texto": "(144810+144815+144820+144825+145410+145415+145420+145425+145510+145515+145520+145525) / (1454+1455+1448)",
            **calc_indicador(
                ["144810","144815","144820","144825","145410","145415","145420","145425","145510","145515","145520","145525"],
                ["1454","1455","1448"]
            ),
        },
        "vivienda": {
            "nombre": "Vivienda",
            "concepto": "Calidad x Riesgo (B,C,D,E)",
            "descripcion_formula": "Cartera Calificada en Categorías B, C, D y E 'Vivienda' / Cartera Bruta 'Vivienda'",
            "formula_texto": "(140410+140415+140420+140425+140510+140515+140520+140525+146910+146915+146920+146925) / (1404+1405+146905+146910+146915+146920+146925)",
            **calc_indicador(
                ["140410","140415","140420","140425","140510","140515","140520","140525","146910","146915","146920","146925"],
                ["1404","1405","146905","146910","146915","146920","146925"]
            ),
        },
    }
    
    # === INDICADORES POR MORA (Cartera Vencida / Cartera Bruta) ===
    indicadores_mora_modalidad = {
        "consumo_sin_libranza": {
            "nombre": "Consumo Sin Libranza",
            "concepto": "Calidad x Mora (>30 días)",
            "descripcion_formula": "Cartera Vencida 'Consumo SL' / Cartera Bruta 'Consumo SL'",
            "formula_texto": "(Sumatoria cartera consumo SL con más de 30 días de mora) / (1412+1442)",
            **calc_indicador(
                ["841510","841515","841520","841525"],
                ["1412","1442"]
            ),
        },
        "consumo_con_libranza": {
            "nombre": "Consumo Con Libranza",
            "concepto": "Calidad x Mora (>30 días)",
            "descripcion_formula": "Cartera Vencida 'Consumo CL' / Cartera Bruta 'Consumo CL'",
            "formula_texto": "(Sumatoria cartera consumo CL con más de 30 días de mora) / (1411+1441+146930+146935+146940+146945+146950)",
            **calc_indicador(
                ["841010","841015","841020","841025"],
                ["1411","1441","146930","146935","146940","146945","146950"]
            ),
        },
        "comercial": {
            "nombre": "Comercial",
            "concepto": "Calidad x Mora (>30 días)",
            "descripcion_formula": "Cartera Vencida 'Comercial' / Cartera Bruta 'Comercial'",
            "formula_texto": "(Sumatoria cartera comercial con más de 30 días de mora) / (1461+1462)",
            **calc_indicador(
                ["842510","842515","842520","842525"],
                ["1461","1462"]
            ),
        },
        "microcredito": {
            "nombre": "Microcrédito",
            "concepto": "Calidad x Mora (>30 días)",
            "descripcion_formula": "Cartera Vencida 'Microcrédito' / Cartera Bruta 'Microcrédito'",
            "formula_texto": "(Sumatoria cartera microcrédito con más de 30 días de mora) / (1448+1454+1455)",
            **calc_indicador(
                ["842010","842015","842020","842025"],
                ["1448","1454","1455"]
            ),
        },
        "vivienda": {
            "nombre": "Vivienda",
            "concepto": "Calidad x Mora (>60 días)",
            "descripcion_formula": "Cartera Vencida 'Vivienda' / Cartera Bruta 'Vivienda'",
            "formula_texto": "(Sumatoria cartera de vivienda con más de 60 días de mora) / (1404+1405+146905+146910+146915+146920+146925)",
            **calc_indicador(
                ["840510","840515","840520","840525"],
                ["1404","1405","146905","146910","146915","146920","146925"]
            ),
        },
    }
    
    # Saldos individuales de cuentas PUC para reporte auditable
    cuentas_riesgo = [
        # Vivienda
        '140410','140415','140420','140425','140510','140515','140520','140525',
        '146905','146910','146915','146920','146925',
        # Consumo CL
        '141110','141115','141120','141125','144110','144115','144120','144125',
        '146930','146935','146940','146945','146950',
        # Consumo SL
        '141210','141215','141220','141225','144210','144215','144220','144225',
        # Microcrédito
        '144810','144815','144820','144825','145410','145415','145420','145425',
        '145510','145515','145520','145525',
        # Comercial
        '146110','146115','146120','146125','146210','146215','146220','146225',
        # 4 dígitos (cartera bruta)
        '1404','1405','1411','1412','1441','1442','1448','1454','1455','1461','1462','1469',
    ]
    saldos_cuentas_riesgo = {}
    for c in cuentas_riesgo:
        s = df_p[df_p["CUENTA"] == c]["NUEVO SALDO"].abs().sum()
        saldos_cuentas_riesgo[c] = s / 1_000_000

    return {
        "periodo": f"{mes.upper()} {anio}",
        "anio": anio,
        "mes": mes.upper(),
        "items_bruta": items_bruta,
        "cartera_total": cartera_total,
        "cartera_A": cartera_A,
        "cartera_B": totales["B"],
        "cartera_C": totales["C"],
        "cartera_D": totales["D"],
        "cartera_E": totales["E"],
        "total_bcde": total_bcde,
        "calidad_cartera": calidad_cartera,
        "detalle_categorias": detalle_categorias,
        "indicadores_riesgo_modalidad": indicadores_riesgo_modalidad,
        "indicadores_mora_modalidad": indicadores_mora_modalidad,
        "saldos_cuentas": saldos_cuentas_riesgo,
    }



def calcular_cobertura(df: pd.DataFrame, anio: int, mes: str) -> dict:
    """
    Calcula el Indicador de Cobertura de Cartera por modalidad.
    
    Cobertura = Deterioro / Cartera Vencida (categorías B, C, D y E)
    
    Indica qué porcentaje de la cartera vencida está cubierto por
    provisiones de deterioro contables.
    """
    df_p = df[(df["AÑO"] == anio) & (df["MES"] == mes.upper())]
    
    def sumar_exacta(cuenta: str) -> float:
        s = df_p[df_p["CUENTA"] == cuenta]["NUEVO SALDO"].abs().sum()
        return s / 1_000_000  # millones
    
    def calc_indicador(num_cuentas, den_cuentas):
        num = sum(sumar_exacta(c) for c in num_cuentas)
        den = sum(sumar_exacta(c) for c in den_cuentas)
        indice = (num / den) if den > 0 else 0.0
        return {
            "numerador": num,
            "denominador": den,
            "indice": indice,
            "num_cuentas": num_cuentas,
            "den_cuentas": den_cuentas,
        }
    
    # === INDICADORES DE COBERTURA POR MODALIDAD ===
    # Orden: Consumo → Vivienda → Microcrédito Empresarial → Comercial
    indicadores_cobertura = {
        "consumo": {
            "nombre": "Consumo",
            "concepto": "Cobertura (B,C,D,E)",
            "descripcion_formula": "Deterioro Consumo / Cartera Vencida Consumo (categorías B+C+D+E)",
            "formula_texto": "(144505+...+144550+147130+...+147150) / (141110+...+141225+144110+...+144225+146935+...+146950)",
            **calc_indicador(
                ["144505","144510","144515","144520","144525","144530","144535","144540","144545","144550",
                 "147130","147135","147140","147145","147150"],
                ["141110","141115","141120","141125","141210","141215","141220","141225",
                 "144110","144115","144120","144125","144210","144215","144220","144225",
                 "146935","146940","146945","146950"]
            ),
        },
        "vivienda": {
            "nombre": "Vivienda",
            "concepto": "Cobertura (B,C,D,E)",
            "descripcion_formula": "Deterioro Vivienda / Cartera Vencida Vivienda (categorías B+C+D+E)",
            "formula_texto": "(140805+...+140825+147105+...+147125) / (140410+...+140525+146910+...+146925)",
            **calc_indicador(
                ["140805","140810","140815","140820","140825",
                 "147105","147110","147115","147120","147125"],
                ["140410","140415","140420","140425","140510","140515","140520","140525",
                 "146910","146915","146920","146925"]
            ),
        },
        "microcredito_empresarial": {
            "nombre": "Microcrédito Empresarial",
            "concepto": "Cobertura (B,C,D,E)",
            "descripcion_formula": "Deterioro Microcrédito Empresarial / Cartera Vencida (categorías B+C+D+E)",
            "formula_texto": "(145805+...+145850) / (145410+...+145525)",
            **calc_indicador(
                ["145805","145810","145815","145820","145825","145830","145835","145840","145845","145850"],
                ["145410","145415","145420","145425","145510","145515","145520","145525"]
            ),
        },
        "comercial": {
            "nombre": "Comercial",
            "concepto": "Cobertura (B,C,D,E)",
            "descripcion_formula": "Deterioro Comercial / Cartera Vencida Comercial (categorías B+C+D+E)",
            "formula_texto": "(145805+...+145850) / (145410+...+145425+145510+...+145525)",
            **calc_indicador(
                ["145805","145810","145815","145820","145825","145830","145835","145840","145845","145850"],
                ["145410","145415","145420","145425","145510","145515","145520","145525"]
            ),
        },
    }
    
    # Totales globales (suma de deterioros / suma de vencidas)
    # Para evitar duplicar Comercial y Microcrédito Empresarial (que comparten cuentas),
    # solo sumamos Consumo, Comercial y Vivienda (Microcrédito Empresarial duplica Comercial)
    total_deterioro = (indicadores_cobertura["consumo"]["numerador"] +
                       indicadores_cobertura["comercial"]["numerador"] +
                       indicadores_cobertura["vivienda"]["numerador"])
    total_vencida = (indicadores_cobertura["consumo"]["denominador"] +
                     indicadores_cobertura["comercial"]["denominador"] +
                     indicadores_cobertura["vivienda"]["denominador"])
    cobertura_total = (total_deterioro / total_vencida) if total_vencida > 0 else 0.0
    
    # === PROVISIÓN GENERAL (cuenta 1468) ===
    # Cuenta 1468 = Deterioro general de cartera de créditos
    # Subcuentas: 146805 (general) + 146810 (general adicional)
    provision_general = sumar_exacta("1468")
    provision_general_805 = sumar_exacta("146805")
    provision_general_810 = sumar_exacta("146810")
    
    # Cobertura CON provisión general
    total_deterioro_con_gral = total_deterioro + provision_general
    cobertura_total_con_gral = (total_deterioro_con_gral / total_vencida) if total_vencida > 0 else 0.0
    
    # Saldos individuales de cuentas PUC (auditable)
    cuentas_cobertura = [
        # Deterioros
        '144505','144510','144515','144520','144525','144530','144535','144540','144545','144550',
        '147130','147135','147140','147145','147150',
        '140805','140810','140815','140820','140825',
        '147105','147110','147115','147120','147125',
        '145805','145810','145815','145820','145825','145830','145835','145840','145845','145850',
        # Provisión general (NUEVAS cuentas para auditoría)
        '1468','146805','146810',
        # Cartera vencida B,C,D,E (denominadores)
        '141110','141115','141120','141125','141210','141215','141220','141225',
        '144110','144115','144120','144125','144210','144215','144220','144225',
        '146935','146940','146945','146950',
        '140410','140415','140420','140425','140510','140515','140520','140525',
        '146910','146915','146920','146925',
        '145410','145415','145420','145425','145510','145515','145520','145525',
    ]
    saldos_cuentas_cob = {}
    for c in cuentas_cobertura:
        s = df_p[df_p["CUENTA"] == c]["NUEVO SALDO"].abs().sum()
        saldos_cuentas_cob[c] = s / 1_000_000
    
    return {
        "periodo": f"{mes.upper()} {anio}",
        "anio": anio,
        "mes": mes.upper(),
        "indicadores_cobertura": indicadores_cobertura,
        "total_deterioro": total_deterioro,
        "total_vencida": total_vencida,
        "cobertura_total": cobertura_total,
        "provision_general": provision_general,
        "provision_general_805": provision_general_805,
        "provision_general_810": provision_general_810,
        "total_deterioro_con_gral": total_deterioro_con_gral,
        "cobertura_total_con_gral": cobertura_total_con_gral,
        "saldos_cuentas": saldos_cuentas_cob,
    }


def calcular_crecimiento(df: pd.DataFrame, anio: int, mes: str) -> dict:
    """
    Calcula los indicadores de Crecimiento de Cartera (anual interanual).
    
    Fórmula: (Periodo Actual / Mismo Período Año Anterior) - 1
    
    Indicadores (basados en el Anexo Técnico):
      1. Cartera Bruta Total (todas las cuentas 4 dígitos)
      2. Consumo Sin Libranza (1412+1442)
      3. Consumo Con Libranza (1411+1441+146930+...+146950)
      4. Comercial (1461+1462)
      5. Microcrédito (1448+1454+1455)
      6. Vivienda (1404+1405+146905+...+146925)
      7. Cartera Capital por Riesgo (B+C+D+E de todas las modalidades)
    
    Si no hay período anterior disponible (primer año), devuelve None en crecimiento.
    """
    anio_anterior = anio - 1
    
    def sumar_cuentas(periodo_anio: int, periodo_mes: str, cuentas: list) -> float:
        df_p = df[(df["AÑO"] == periodo_anio) & (df["MES"] == periodo_mes.upper())]
        s = sum(
            df_p[df_p["CUENTA"] == c]["NUEVO SALDO"].abs().sum()
            for c in cuentas
        )
        return s / 1_000_000  # millones
    
    def calc_crec(cuentas):
        actual = sumar_cuentas(anio, mes, cuentas)
        anterior = sumar_cuentas(anio_anterior, mes, cuentas)
        if anterior > 0:
            crecimiento = (actual / anterior) - 1
            tiene_dato = True
        else:
            crecimiento = 0.0
            tiene_dato = (actual > 0)  # solo False si ambos son cero (sin cartera)
        return {
            "actual": actual,
            "anterior": anterior,
            "crecimiento": crecimiento,
            "tiene_dato_anterior": anterior > 0,
            "sin_cartera": (actual == 0 and anterior == 0),
            "cuentas": cuentas,
        }
    
    # === INDICADORES DE CRECIMIENTO ===
    # Orden: Total → Consumo SL → Consumo CL → Comercial → Microcrédito → Vivienda → Riesgo
    indicadores_crecimiento = {
        "total": {
            "nombre": "Cartera Bruta Total",
            "concepto": "Crecimiento Cartera Bruta Total",
            "descripcion_formula": "(Cartera Bruta período Actual / Cartera Bruta mismo período año anterior) − 1",
            "formula_texto": "(1404+1405+1411+1412+1441+1442+1448+1454+1455+1461+1462+1469) actual / (mismo) anterior − 1",
            **calc_crec(["1404","1405","1411","1412","1441","1442","1448","1454","1455","1461","1462","1469"]),
        },
        "consumo_sin_libranza": {
            "nombre": "Consumo Sin Libranza",
            "concepto": "Crecimiento Cartera Consumo SL",
            "descripcion_formula": "(Cartera Bruta Consumo SL actual / mismo período año anterior) − 1",
            "formula_texto": "(1412+1442) actual / (1412+1442) anterior − 1",
            **calc_crec(["1412","1442"]),
        },
        "consumo_con_libranza": {
            "nombre": "Consumo Con Libranza",
            "concepto": "Crecimiento Cartera Consumo CL",
            "descripcion_formula": "(Cartera Bruta Consumo CL actual / mismo período año anterior) − 1",
            "formula_texto": "(1411+1441+146930+146935+146940+146945+146950) actual / (mismo) anterior − 1",
            **calc_crec(["1411","1441","146930","146935","146940","146945","146950"]),
        },
        "comercial": {
            "nombre": "Comercial",
            "concepto": "Crecimiento Cartera Comercial",
            "descripcion_formula": "(Cartera Bruta Comercial actual / mismo período año anterior) − 1",
            "formula_texto": "(1461+1462) actual / (1461+1462) anterior − 1",
            **calc_crec(["1461","1462"]),
        },
        "microcredito": {
            "nombre": "Microcrédito",
            "concepto": "Crecimiento Cartera Microcrédito",
            "descripcion_formula": "(Cartera Bruta Microcrédito actual / mismo período año anterior) − 1",
            "formula_texto": "(1448+1454+1455) actual / (1448+1454+1455) anterior − 1",
            **calc_crec(["1448","1454","1455"]),
        },
        "vivienda": {
            "nombre": "Vivienda",
            "concepto": "Crecimiento Cartera Vivienda",
            "descripcion_formula": "(Cartera Bruta Vivienda actual / mismo período año anterior) − 1",
            "formula_texto": "(1404+1405+146905+146910+146915+146920+146925) actual / (mismo) anterior − 1",
            **calc_crec(["1404","1405","146905","146910","146915","146920","146925"]),
        },
        "riesgo": {
            "nombre": "Cartera Capital por Riesgo",
            "concepto": "Crecimiento Cartera en Riesgo (B+C+D+E)",
            "descripcion_formula": "(Cartera en riesgo período actual / Cartera en riesgo mismo período año anterior) − 1",
            "formula_texto": "Suma de categorías B,C,D,E de todas las modalidades (vencidas)",
            **calc_crec([
                "140410","140415","140420","140425","140510","140515","140520","140525",
                "141110","141115","141120","141125","141210","141215","141220","141225",
                "144110","144115","144120","144125","144210","144215","144220","144225",
                "144810","144815","144820","144825","145410","145415","145420","145425",
                "145510","145515","145520","145525","146110","146115","146120","146125",
                "146210","146215","146220","146225","146910","146915","146920","146925",
                "146935","146940","146945","146950"
            ]),
        },
    }
    
    # Datos generales
    total_actual = indicadores_crecimiento["total"]["actual"]
    total_anterior = indicadores_crecimiento["total"]["anterior"]
    crecimiento_total = indicadores_crecimiento["total"]["crecimiento"]
    tiene_anterior = indicadores_crecimiento["total"]["tiene_dato_anterior"]
    
    # Saldos individuales de cuentas (actual y anterior) para reporte auditable
    cuentas_crec = [
        '1404','1405','1411','1412','1441','1442','1448','1454','1455','1461','1462','1469',
        '146905','146910','146915','146920','146925',
        '146930','146935','146940','146945','146950',
    ]
    df_actual = df[(df["AÑO"] == anio) & (df["MES"] == mes.upper())]
    df_anterior = df[(df["AÑO"] == anio_anterior) & (df["MES"] == mes.upper())]
    saldos_actual = {}
    saldos_anterior = {}
    for c in cuentas_crec:
        sa = df_actual[df_actual["CUENTA"] == c]["NUEVO SALDO"].abs().sum() / 1_000_000
        san = df_anterior[df_anterior["CUENTA"] == c]["NUEVO SALDO"].abs().sum() / 1_000_000
        saldos_actual[c] = sa
        saldos_anterior[c] = san
    
    return {
        "periodo": f"{mes.upper()} {anio}",
        "anio": anio,
        "mes": mes.upper(),
        "anio_anterior": anio_anterior,
        "indicadores_crecimiento": indicadores_crecimiento,
        "total_actual": total_actual,
        "total_anterior": total_anterior,
        "crecimiento_total": crecimiento_total,
        "tiene_dato_anterior": tiene_anterior,
        "saldos_actual": saldos_actual,
        "saldos_anterior": saldos_anterior,
    }


