def _signo_y_clave(item: str):
    return (-1.0, item[1:]) if item.startswith("-") else (1.0, item)


def _evaluar_filas(filas: list, valor_cuenta) -> dict:
    """Calcula cada fila (en orden) con `valor_cuenta(cuenta) -> float|None`.
    Devuelve {id_fila: valor}. None se propaga (período sin dato).
    Primero se calculan las filas de cuentas y luego las de suma/ratio, para
    que un grupo pueda sumar filas de detalle que aparecen debajo de él."""
    def combinar(partes):
        return None if any(v is None for _, v in partes) else sum(s * v for s, v in partes)
    res = {}
    for f in filas:
        if f.get("id") and "cuentas" in f:
            res[f["id"]] = combinar([(s, valor_cuenta(c)) for s, c in map(_signo_y_clave, f["cuentas"])])
    for f in filas:
        fid = f.get("id")
        if not fid or "cuentas" in f:
            continue
        if f.get("tipo") == "ratio":
            num, den = (res.get(f["ratio"][0]), res.get(f["ratio"][1]))
            res[fid] = (num / den) if (num is not None and den) else None
        else:
            res[fid] = combinar([(s, res.get(k)) for s, k in map(_signo_y_clave, f.get("suma", []))])
    return res


# Sentido de la variación para el semáforo: +1 = subir es favorable (verde),
# −1 = subir es desfavorable (rojo), 0 = neutro (flecha gris, sin semáforo).
# Una fila puede fijarlo con la clave "sentido"; si no, se deduce así:
_SENTIDO_POR_ID = {
    "total_activos": 1, "total_patrimonio": 1, "total_pasivos": 0, "total_pas_pat": 0,
    "res_bruto": 1, "res_op": 1, "res_neto": 1, "tot_gop": -1,
    "tot_ing": 1, "tot_gc": -1, "exc_op": 1, "margen_op": 1,
}


def _sentido_fila(f: dict, sentido_seccion: int | None) -> int:
    if "sentido" in f:
        return f["sentido"]
    tipo = f.get("tipo", "cuenta")
    if tipo in ("titulo", "control", "acumulado"):
        return 0
    if f.get("id") in _SENTIDO_POR_ID:
        return _SENTIDO_POR_ID[f["id"]]
    cuentas = [c for c in f.get("cuentas", []) if not c.startswith("-")]
    if cuentas:
        c = cuentas[0]
        if c.startswith("21"):        # depósitos: crecer es favorable
            return 1
        return {"1": 1, "2": -1, "3": 1, "4": 1, "5": -1, "6": -1}.get(c[0], 0)
    return sentido_seccion or 0       # totales y grupos de una sección de detalle


def _filas_meta(filas: list, control=None) -> list:
    """Metadatos de cada fila para el HTML (sin valores)."""
    ctrl = control[0] if isinstance(control, list) else control
    sentido_seccion = _sentido_fila({"cuentas": [ctrl]}, None) if ctrl else None
    meta = []
    for f in filas:
        cuentas = f.get("cuentas", [])
        meta.append({
            "id": f.get("id"),
            "tipo": f.get("tipo", "cuenta"),
            "etiqueta": f["etiqueta"],
            "codigo": " + ".join(c for c in cuentas if not c.startswith("-")) if cuentas else "",
            "nivel": f.get("nivel", 0),
            "base": f.get("base"),
            "suma": f.get("suma"),
            "ratio": f.get("ratio"),
            "sentido": _sentido_fila(f, sentido_seccion),
        })
    return meta


def calcular_estados_financieros(df: pd.DataFrame, periodos: list[tuple[int, str]],
                                 verbose: bool = True) -> dict:
    """
    Calcula el E.S.F. Mensual y el E.R.I. Mensual para todos los períodos.

    Retorna:
      {
        "periodos": [{"anio", "mes"}, ...],
        "esf": {"filas": [meta...], "valores": {id: [v por período]}},
        "eri": {"secciones": [{"id", "titulo", "filas": [meta...],
                               "mensual": {id: [...]}, "acumulado": {id: [...]}}]}
      }
    Todos los valores en millones de pesos.
    """
    meses_orden = ["ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO",
                   "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"]
    saldos = (df.groupby(["AÑO", "MES", "CUENTA"])["NUEVO SALDO"].sum() / 1_000_000).to_dict()
    disponibles = {(a, m.upper()) for a, m in periodos}

    def saldo(anio, mes, cuenta):
        return saldos.get((anio, mes, cuenta), 0.0)

    def mes_anterior(anio, mes):
        i = meses_orden.index(mes)
        return (anio - 1, "DICIEMBRE") if i == 0 else (anio, meses_orden[i - 1])

    def movimiento(anio, mes, cuenta):
        """Movimiento del mes = acumulado del mes − acumulado del mes anterior."""
        if mes == "ENERO":
            return saldo(anio, mes, cuenta)
        a_ant, m_ant = mes_anterior(anio, mes)
        if (a_ant, m_ant) not in disponibles:
            return None
        return saldo(anio, mes, cuenta) - saldo(a_ant, m_ant, cuenta)

    lista_periodos = [{"anio": a, "mes": m.upper()} for a, m in periodos]

    def _r(v):
        return None if v is None else round(v, 4)

    # --- E.S.F.: saldo del mes ---
    esf_valores = {f["id"]: [] for f in ESTRUCTURA_ESF if f.get("id")}
    for p in lista_periodos:
        r = _evaluar_filas(ESTRUCTURA_ESF, lambda c, p=p: saldo(p["anio"], p["mes"], c))
        for k in esf_valores:
            esf_valores[k].append(_r(r.get(k)))

    # --- E.R.I.: movimiento del mes y acumulado del año ---
    secciones = []
    avisos = []
    for sec in ESTRUCTURA_ERI:
        mensual = {f["id"]: [] for f in sec["filas"] if f.get("id")}
        acumulado = {f["id"]: [] for f in sec["filas"] if f.get("id")}
        for p in lista_periodos:
            a, m = p["anio"], p["mes"]
            rm = _evaluar_filas(sec["filas"], lambda c: movimiento(a, m, c))
            ra = _evaluar_filas(sec["filas"], lambda c: saldo(a, m, c))
            # El "Resultado Neto Acumulado" es el resultado del año a la fecha,
            # tanto en la vista mensual como en la acumulada.
            for f in sec["filas"]:
                if f.get("tipo") == "acumulado":
                    rm[f["id"]] = ra[f["id"]]
            for k in mensual:
                mensual[k].append(_r(rm.get(k)))
                acumulado[k].append(_r(ra.get(k)))
            # Validación: el detalle debe sumar lo mismo que la cuenta mayor
            if sec.get("control") and ra.get("tot") is not None:
                ctrl = sec["control"] if isinstance(sec["control"], list) else [sec["control"]]
                esperado = sum(saldo(a, m, c) for c in ctrl)
                if abs(esperado - ra["tot"]) > 0.01:
                    avisos.append(f"{sec['titulo']} {m} {a}: detalle {ra['tot']:,.2f} "
                                  f"vs cuenta {'+'.join(ctrl)} {esperado:,.2f}")
        secciones.append({
            "id": sec["id"], "titulo": sec["titulo"],
            "control": sec.get("control"),
            "filas": _filas_meta(sec["filas"], sec.get("control")),
            "mensual": mensual, "acumulado": acumulado,
        })

    if verbose and avisos:
        print(f"   AVISO: {len(avisos)} período(s) donde el detalle del E.R.I. no cuadra con la cuenta mayor:")
        for a in avisos[-10:]:
            print(f"     - {a}")

    return {
        "periodos": lista_periodos,
        "esf": {"filas": _filas_meta(ESTRUCTURA_ESF), "valores": esf_valores},
        "eri": {"secciones": secciones},
        "cuentas": _saldos_subcuentas(df, periodos),
    }


def _saldos_subcuentas(df: pd.DataFrame, periodos: list[tuple[int, str]]) -> dict:
    """Saldos (millones, acumulados) de las cuentas de 4, 6 y 9 dígitos de las
    clases 1 a 6, para el botón "+" que desagrega cuentas en el E.S.F. / E.R.I.
    Retorna {codigo: [nombre, [saldo por período]]}; omite cuentas siempre en cero.
    El movimiento mensual del E.R.I. se calcula en el navegador a partir de estos saldos."""
    def limpiar(nombre) -> str:
        n = (str(nombre).strip().replace('\x90', 'É').replace('\x84', 'á').replace('\x8a', 'é')
             .replace('\xa1', 'í').replace('\x82', 'é').replace('\xa3', 'ó').replace('\xa2', 'ó')
             .replace('\xe0', 'Ó').replace('\xc0', 'Ó').replace('\xd6', 'Í').replace('\xcc', 'Í')
             .replace('PéBLIC', 'PÚBLIC').replace('\xa0', ' '))
        n = re.sub(r"[EÉ]É|ÉE", "É", n)          # "CREÉDITOS" / "CRÉEDITOS" → "CRÉDITOS"
        n = re.sub(r"\s+", " ", n)
        return n[:1].upper() + n[1:].lower()
    sub = df[df["CUENTA"].str.len().isin([4, 6, 9]) & df["CUENTA"].str[0].isin(list("123456"))]
    tabla = sub.pivot_table(index="CUENTA", columns=["AÑO", "MES"], values="NUEVO SALDO",
                            aggfunc="sum", fill_value=0.0) / 1_000_000
    cols = [(a, m.upper()) for a, m in periodos]
    tabla = tabla.reindex(columns=pd.MultiIndex.from_tuples(cols), fill_value=0.0).round(2)
    tabla = tabla[(tabla.abs() > 0.004).any(axis=1)]
    nombres = sub.drop_duplicates("CUENTA", keep="last").set_index("CUENTA")["NOMBRE CUENTA"]
    return {cod: [limpiar(nombres.get(cod, cod)), [float(v) for v in fila]]
            for cod, fila in zip(tabla.index, tabla.values)}


