                {{ header: 'Ingresos (41)', key: 'c41', width: 16 }},
                {{ header: 'Costos (61)', key: 'c61', width: 16 }},
                {{ header: 'Gasto 5105', key: 'g1', width: 14 }},
                {{ header: 'Gasto 5110', key: 'g2', width: 14 }},
                {{ header: 'Gasto 5115', key: 'g3', width: 14 }},
                {{ header: 'Gasto 5125', key: 'g4', width: 14 }},
                {{ header: 'Recup. 4225', key: 'r4', width: 14 }},
                {{ header: 'Margen Fin. Bruto', key: 'mfb', width: 18 }},
                {{ header: 'Gastos Op. Netos', key: 'gn', width: 18 }},
